package com.ringback.app

import android.Manifest
import android.app.*
import android.app.role.RoleManager
import android.content.Intent
import android.content.pm.PackageManager
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.provider.ContactsContract
import android.provider.Settings
import android.view.Gravity
import android.view.View
import android.widget.*
import java.text.SimpleDateFormat
import java.util.*

class MainActivity : Activity() {
    private val bg=Color.rgb(0,61,50); private val card=Color.rgb(5,87,72); private val accent=Color.rgb(70,230,178); private val fg=Color.rgb(240,255,249); private val muted=Color.rgb(166,205,194)
    private lateinit var content:LinearLayout; private var tab=0; private var manualName=""; private var manualNumber=""; private var manualNote=""

    override fun onCreate(b:Bundle?){super.onCreate(b);window.statusBarColor=Color.rgb(248,247,250);window.navigationBarColor=Color.rgb(248,247,250);window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;calls()}
    override fun onResume(){super.onResume();if(::content.isInitialized)refresh()}
    private fun refresh(){when(tab){0->calls();1->settings();2->permissions()}}

    private fun shell():LinearLayout{val r=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(bg)};val s=ScrollView(this);content=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(18),dp(20),dp(90))};s.addView(content);r.addView(s,LinearLayout.LayoutParams(-1,0,1f));val nav=LinearLayout(this).apply{setBackgroundColor(Color.rgb(0,52,44))};listOf("☎\nLlamadas","⚙\nAjustes","♢\nPermisos").forEachIndexed{i,x->nav.addView(tv(x,14f,if(i==tab)accent else muted,true).apply{gravity=Gravity.CENTER;setOnClickListener{tab=i;refresh()}},LinearLayout.LayoutParams(0,dp(72),1f))};r.addView(nav);return r}

    private fun calls(){tab=0;setContentView(shell());val pending=CallDb(this).pending();val h=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL};val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};l.addView(tv("Llamadas pendientes",28f,fg,true));l.addView(tv("${pending.size} llamadas por devolver",15f,muted));h.addView(l,LinearLayout.LayoutParams(0,-2,1f));h.addView(button("＋  Programar",accent,fg).apply{setOnClickListener{manualSchedule()}},LinearLayout.LayoutParams(dp(145),dp(54)));content.addView(h);content.addView(tv("RingBack aparece al terminar una llamada y te permite decidir cuándo devolverla. No sustituye a la aplicación Teléfono.",13f,muted).apply{setPadding(0,dp(8),0,dp(14))})
        if(pending.isNotEmpty()){section("POR DEVOLVER");pending.forEach{pendingCard(it)}}
        section("HISTORIAL");val all=CallDb(this).all();if(all.isEmpty())content.addView(tv("☎\n\nTodavía no hay llamadas registradas.",20f,muted).apply{gravity=Gravity.CENTER;setPadding(0,dp(70),0,0)}) else all.take(30).forEach{historyCard(it)}
    }

    private fun pendingCard(r:CallRecord){val b=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(15),dp(15),dp(15),dp(15));background=round(card,20,Color.rgb(48,135,114))};b.addView(tv(r.name,19f,fg,true));b.addView(tv(SimpleDateFormat("EEEE dd/MM · HH:mm",Locale.getDefault()).format(Date(r.reminderAt?:0)),14f,accent,true));if(r.note.isNotBlank())b.addView(tv("📝 ${r.note}",14f,fg));val a=LinearLayout(this);a.addView(button("☎ Llamar",accent,fg).apply{setOnClickListener{startActivity(Intent(Intent.ACTION_DIAL,Uri.parse("tel:${Uri.encode(r.number)}"))) }},LinearLayout.LayoutParams(0,dp(48),1f).apply{setMargins(3,8,3,3)});a.addView(button("Posponer",accent,fg).apply{setOnClickListener{postpone(r)}},LinearLayout.LayoutParams(0,dp(48),1f).apply{setMargins(3,8,3,3)});a.addView(button("Eliminar",accent,fg).apply{setOnClickListener{ReminderScheduler.cancel(this,r.id);CallDb(this).delete(r.id);calls()}},LinearLayout.LayoutParams(0,dp(48),1f).apply{setMargins(3,8,3,3)});b.addView(a);content.addView(b,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,6,0,6)})}
    private fun historyCard(r:CallRecord){val b=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(15),dp(13),dp(15),dp(13));background=round(card,18,Color.rgb(48,135,114))};b.addView(tv(r.name,18f,fg,true));b.addView(tv(r.type+" · "+SimpleDateFormat("dd/MM HH:mm",Locale.getDefault()).format(Date(r.startedAt)),13f,muted));if(r.note.isNotBlank())b.addView(tv("📝 ${r.note}",14f,fg));content.addView(b,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,5,0,5)})}

    private fun postpone(r:CallRecord){val now=Calendar.getInstance();val choices=arrayOf("5 minutos","10 minutos","15 minutos","30 minutos","1 hora","2 horas","4 horas","Mañana misma hora","Fecha y hora…");AlertDialog.Builder(this).setTitle("Posponer devolución").setItems(choices){_,which->val minutes=listOf(5,10,15,30,60,120,240)[which];if(which<7){val at=System.currentTimeMillis()+minutes*60000L;CallDb(this).updateReminder(r.id,at);ReminderScheduler.schedule(this,r.id,r.copy(reminderAt=at));calls()}else if(which==7){val at=System.currentTimeMillis()+1440*60000L;CallDb(this).updateReminder(r.id,at);ReminderScheduler.schedule(this,r.id,r.copy(reminderAt=at));calls()}else chooseCustomFor(r)}}.show()}
    private fun chooseCustomFor(r:CallRecord){val n=Calendar.getInstance();DatePickerDialog(this,{_,y,m,d->TimePickerDialog(this,{_,h,min->val at=Calendar.getInstance().apply{set(y,m,d,h,min,0);set(Calendar.MILLISECOND,0)}.timeInMillis;if(at<=System.currentTimeMillis()){Toast.makeText(this,"La hora debe ser futura",Toast.LENGTH_SHORT).show();return@TimePickerDialog};CallDb(this).updateReminder(r.id,at);ReminderScheduler.schedule(this,r.id,r.copy(reminderAt=at));calls()},n.get(Calendar.HOUR_OF_DAY),n.get(Calendar.MINUTE),true).show()},n.get(Calendar.YEAR),n.get(Calendar.MONTH),n.get(Calendar.DAY_OF_MONTH)).show()}

    private fun settings(){tab=1;setContentView(shell());content.addView(tv("Ajustes",28f,fg,true));content.addView(tv("Decide qué llamadas generan el pop-up y tu horario de trabajo.",15f,muted));section("POP-UP POST-LLAMADA");sw("Llamadas salientes","Mostrar pop-up al terminar una llamada saliente","outgoing");sw("Llamadas entrantes","Mostrar pop-up al terminar una llamada atendida","incoming");sw("Llamadas perdidas","Mostrar pop-up al detectar una llamada perdida","missed");section("RECORDATORIO PRESELECCIONADO");val times=listOf(5,10,15,30,60,120,240);val g=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};times.chunked(4).forEach{vs->val row=LinearLayout(this);vs.forEach{m->row.addView(button(if(SettingsStore.reminder(this)==m)"✓ ${fmt(m)}" else fmt(m),accent,fg).apply{setOnClickListener{SettingsStore.p(this@MainActivity).edit().putInt("reminder_minutes",m).apply();settings()}},LinearLayout.LayoutParams(0,dp(50),1f).apply{setMargins(3,3,3,3)})};g.addView(row)};content.addView(g);section("HORARIO DE TRABAJO");sw("Limitar pop-up al horario de trabajo","Solo afecta a las llamadas automáticas, no a las programadas manualmente","schedule_enabled");if(SettingsStore.p(this).getBoolean("schedule_enabled",false)){listOf("Lunes" to "mon","Martes" to "tue","Miércoles" to "wed","Jueves" to "thu","Viernes" to "fri","Sábado" to "sat","Domingo" to "sun").forEach{daySwitch(it.first,it.second)};val work=LinearLayout(this);work.addView(button("Inicio ${timeText(SettingsStore.p(this).getInt("work_start",480))}",accent,fg).apply{setOnClickListener{chooseTime("work_start")}},LinearLayout.LayoutParams(0,dp(52),1f).apply{setMargins(3,3,3,3)});work.addView(button("Fin ${timeText(SettingsStore.p(this).getInt("work_end",1080))}",accent,fg).apply{setOnClickListener{chooseTime("work_end")}},LinearLayout.LayoutParams(0,dp(52),1f).apply{setMargins(3,3,3,3)});content.addView(work)};section("VENTANA FLOTANTE");sw("Ocultar pop-up automáticamente","El pop-up desaparece tras unos segundos","autohide");content.addView(button("Configurar ventana sobre otras apps",accent,fg).apply{setOnClickListener{openOverlaySettings()}},LinearLayout.LayoutParams(-1,dp(56)).apply{setMargins(0,8,0,0)})}

    private fun permissions(){tab=2;setContentView(shell());content.addView(tv("Permisos y detección",28f,fg,true));content.addView(tv("RingBack usa el rol de identificación de llamadas de Android para conocer número y dirección sin sustituir a tu teléfono.",15f,muted));section("DETECCIÓN DE LLAMADAS");val roleOk=Build.VERSION.SDK_INT<29||getSystemService(RoleManager::class.java)?.isRoleHeld(RoleManager.ROLE_CALL_SCREENING)==true;perm("Identificación de llamadas", "Necesario para conocer llamadas entrantes y salientes",roleOk);content.addView(button(if(roleOk)"✓ Detección activada" else "Activar detección",accent,fg).apply{isEnabled=!roleOk;setOnClickListener{requestCallScreeningRole()}},LinearLayout.LayoutParams(-1,dp(58)).apply{setMargins(0,8,0,0)});section("PERMISOS");perm("READ_PHONE_STATE","Detectar cambios de estado de la línea",ok(Manifest.permission.READ_PHONE_STATE));perm("READ_CONTACTS","Mostrar nombres de tus contactos",ok(Manifest.permission.READ_CONTACTS));if(Build.VERSION.SDK_INT>=33)perm("POST_NOTIFICATIONS","Mostrar recordatorios",ok(Manifest.permission.POST_NOTIFICATIONS));perm("Ventana sobre otras apps","Mostrar el pop-up encima de otras aplicaciones",Settings.canDrawOverlays(this));if(Build.VERSION.SDK_INT>=31)perm("Alarmas y recordatorios","Permite intentar avisar a la hora elegida con precisión",getSystemService(AlarmManager::class.java).canScheduleExactAlarms());content.addView(button("Conceder permisos necesarios",accent,fg).apply{setOnClickListener{requestRuntimePermissions()}},LinearLayout.LayoutParams(-1,dp(58)).apply{setMargins(0,12,0,0)});if(Build.VERSION.SDK_INT>=31&&!getSystemService(AlarmManager::class.java).canScheduleExactAlarms())content.addView(button("Permitir alarmas exactas",accent,fg).apply{setOnClickListener{startActivity(Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:$packageName")))}},LinearLayout.LayoutParams(-1,dp(58)).apply{setMargins(0,8,0,0)})}

    private fun requestCallScreeningRole(){if(Build.VERSION.SDK_INT<29){Toast.makeText(this,"La detección avanzada necesita Android 10 o superior.",Toast.LENGTH_LONG).show();return};val rm=getSystemService(RoleManager::class.java);if(rm?.isRoleAvailable(RoleManager.ROLE_CALL_SCREENING)==true)startActivityForResult(rm.createRequestRoleIntent(RoleManager.ROLE_CALL_SCREENING),100)else Toast.makeText(this,"El teléfono no ofrece este rol.",Toast.LENGTH_LONG).show()}
    private fun requestRuntimePermissions(){val list=mutableListOf(Manifest.permission.READ_PHONE_STATE,Manifest.permission.READ_CONTACTS);if(Build.VERSION.SDK_INT>=33)list+=Manifest.permission.POST_NOTIFICATIONS;requestPermissions(list.toTypedArray(),9)}
    override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,grantResults:IntArray){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==9)openOverlaySettings()}
    private fun openOverlaySettings(){try{startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:$packageName")))}catch(_:Exception){startActivity(Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION))}}

    private fun manualSchedule(){
        manualName=""; manualNumber=""; manualNote=""
        val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(10),dp(20),0)}
        val contact=TextView(this).apply{text="Ningún contacto seleccionado";textSize=16f;setTextColor(fg);setPadding(0,dp(10),0,dp(10))}
        val pick=button("Seleccionar contacto",accent,fg).apply{setOnClickListener{startActivityForResult(Intent(Intent.ACTION_PICK,ContactsContract.CommonDataKinds.Phone.CONTENT_URI),200)}}
        val number=EditText(this).apply{hint="Número de teléfono (si no eliges contacto)";inputType=2;setTextColor(fg);setHintTextColor(muted)}
        val note=EditText(this).apply{hint="Motivo (opcional)";setTextColor(fg);setHintTextColor(muted)}
        box.addView(contact);box.addView(pick);box.addView(number);box.addView(note)
        AlertDialog.Builder(this).setTitle("Programar llamada").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Elegir fecha y hora"){_,_->
            val n=if(number.text.isNotBlank()) number.text.toString() else manualNumber
            val name=if(manualName.isBlank()) n else manualName
            chooseManualDate(n,name,note.text.toString())
        }.show()
    }

    private fun chooseManualDate(number:String,name:String,note:String){if(number.isBlank()){Toast.makeText(this,"Selecciona un contacto o introduce un número",Toast.LENGTH_SHORT).show();return};val n=Calendar.getInstance();DatePickerDialog(this,{_,y,m,d->TimePickerDialog(this,{_,h,min->val at=Calendar.getInstance().apply{set(y,m,d,h,min,0);set(Calendar.MILLISECOND,0)}.timeInMillis;if(at<=System.currentTimeMillis()){Toast.makeText(this,"La hora debe ser futura",Toast.LENGTH_SHORT).show();return@TimePickerDialog};val r=CallRecord(number=number,name=if(name.startsWith("Ningún"))number else name.removePrefix("Contacto: "),type="MANUAL",startedAt=System.currentTimeMillis(),durationSec=0,note=note,reminderAt=at,status="PENDING");val id=CallDb(this).insert(r);ReminderScheduler.schedule(this,id,r);Toast.makeText(this,"Llamada programada",Toast.LENGTH_SHORT).show();calls()},n.get(Calendar.HOUR_OF_DAY),n.get(Calendar.MINUTE),true).show()},n.get(Calendar.YEAR),n.get(Calendar.MONTH),n.get(Calendar.DAY_OF_MONTH)).show()}

    override fun onActivityResult(requestCode:Int,resultCode:Int,data:Intent?){
        super.onActivityResult(requestCode,resultCode,data)
        if(requestCode==200&&resultCode==RESULT_OK&&data?.data!=null){
            val uri=data.data!!
            contentResolver.query(uri,arrayOf(ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER),null,null,null)?.use{
                if(it.moveToFirst()){manualName=it.getString(0)?:"Contacto";manualNumber=it.getString(1)?:"";Toast.makeText(this,"Seleccionado: $manualName",Toast.LENGTH_SHORT).show()}
            }
        }
    }

    private fun chooseTime(key:String){val cur=SettingsStore.p(this).getInt(key,if(key=="work_start")480 else 1080);TimePickerDialog(this,{_,h,m->SettingsStore.p(this).edit().putInt(key,h*60+m).apply();settings()},cur/60,cur%60,true).show()}
    private fun daySwitch(title:String,key:String)=sw(title,"","day_$key")
    private fun sw(title:String,desc:String,key:String){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(14),dp(9),dp(8),dp(9));background=round(card,18,Color.rgb(48,135,114))};val l=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};l.addView(tv(title,18f,fg,true));if(desc.isNotBlank())l.addView(tv(desc,13f,muted));row.addView(l,LinearLayout.LayoutParams(0,-2,1f));val checked=if(key=="schedule_enabled")SettingsStore.p(this).getBoolean(key,false) else if(key=="autohide")SettingsStore.autoHide(this)>0 else SettingsStore.p(this).getBoolean(key,key in listOf("day_mon","day_tue","day_wed","day_thu","day_fri"));row.addView(Switch(this).apply{isChecked=checked;setOnCheckedChangeListener{_,v->if(key=="schedule_enabled")SettingsStore.p(this@MainActivity).edit().putBoolean(key,v).apply() else if(key=="autohide")SettingsStore.p(this@MainActivity).edit().putInt("auto_hide_seconds",if(v)15 else 0).apply() else SettingsStore.p(this@MainActivity).edit().putBoolean(key,v).apply()}});content.addView(row,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,5,0,5)})}
    private fun perm(n:String,d:String,good:Boolean){val b=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(14),dp(14),dp(14));background=round(card,18,Color.rgb(48,135,114))};b.addView(tv(n+if(good)"  ✓" else "  !",18f,if(good)accent else Color.rgb(255,190,80),true));b.addView(tv(d,14f,muted));content.addView(b,LinearLayout.LayoutParams(-1,-2).apply{setMargins(0,5,0,5)})}
    private fun section(s:String)=content.addView(tv(s,13f,accent,true).apply{setPadding(0,dp(20),0,dp(7))});private fun ok(p:String)=checkSelfPermission(p)==PackageManager.PERMISSION_GRANTED;private fun fmt(m:Int)=when(m){60->"1 hora";120->"2 horas";240->"4 horas";else->"$m min"};private fun timeText(m:Int)=String.format(Locale.getDefault(),"%02d:%02d",m/60,m%60);private fun tv(s:String,z:Float,c:Int,b:Boolean=false)=TextView(this).apply{text=s;textSize=z;setTextColor(c);setTypeface(null,if(b)1 else 0);setPadding(0,dp(2),0,dp(2))};private fun button(s:String,stroke:Int,c:Int)=tv(s,15f,c,true).apply{gravity=Gravity.CENTER;background=round(Color.rgb(7,84,70),28,stroke)};private fun round(c:Int,r:Int,s:Int)=GradientDrawable().apply{setColor(c);cornerRadius=r.toFloat();setStroke(1,s)};private fun dp(x:Int)=(x*resources.displayMetrics.density).toInt()
}
